<div class="page-heading"><div><span class="eyebrow"><?= $user['role'] === 'OWNER' ? 'COMPANY OVERVIEW' : 'MY SALES DAY' ?></span><h1><?= $user['role'] === 'OWNER' ? 'Pipeline at a glance' : 'Good '.(date('H') < 12 ? 'morning' : 'afternoon').', '.e(explode(' ', $user['name'])[0]) ?></h1><p><?= $user['role'] === 'OWNER' ? 'Track momentum, follow-ups and team activity.' : 'Focus on the conversations that move your leads forward.' ?></p></div><span class="date-pill"><i class="bi bi-calendar3"></i> <?= e(date('D, d M')) ?></span></div>
<?php $cards = [['Total leads','total_leads','people','primary'],['New leads','new_leads','stars','info'],['Due today','due_today','calendar-check','warning'],['Overdue','overdue','exclamation-circle','danger'],['Calls today','calls_today','telephone','success'],['Meetings today','meetings_today','camera-video','violet'],['Won leads','won','trophy','success'],['Lost leads','lost','x-circle','secondary']]; ?>
<div class="row g-3 mb-4"><?php foreach ($cards as [$label,$key,$icon,$tone]): ?><div class="col-6 col-xl-3"><div class="metric-card"><span class="metric-icon tone-<?= e($tone) ?>"><i class="bi bi-<?= e($icon) ?>"></i></span><div><small><?= e($label) ?></small><strong><?= number_format($metrics[$key] ?? 0) ?></strong></div></div></div><?php endforeach; ?></div>
<div class="row g-3 dashboard-panels"><div class="col-xl-7"><section class="panel h-100"><div class="panel-head"><div><span class="eyebrow">SALES PIPELINE</span><h2>Stage distribution</h2></div><a href="<?= e(url('leads')) ?>">View leads <i class="bi bi-arrow-right"></i></a></div><div class="pipeline-list"><?php $stageColors=['NEW'=>'secondary','CONTACTED'=>'info','QUALIFIED'=>'primary','PROPOSAL'=>'warning','NEGOTIATION'=>'dark','WON'=>'success','LOST'=>'danger']; $total=max(1,array_sum($pipeline)); foreach ($pipeline as $stage=>$count): ?><div class="pipeline-row"><div class="pipeline-meta"><span><?= e(ucfirst(strtolower($stage))) ?></span><strong><?= $count ?></strong></div><div class="progress" role="progressbar" aria-label="<?= e(ucfirst(strtolower($stage))) ?>" aria-valuenow="<?= $count ?>" aria-valuemin="0" aria-valuemax="<?= $total ?>"><div class="progress-bar bg-<?= $stageColors[$stage] ?>" style="width:<?= round(($count/$total)*100) ?>%"></div></div></div><?php endforeach; ?></div></section></div><div class="col-xl-5"><section class="panel h-100"><div class="panel-head"><div><span class="eyebrow">FOLLOW-UP FOCUS</span><h2>Needs attention</h2></div><span class="panel-count"><?= count($followUps) ?></span></div><div class="follow-list"><?php if (! $followUps): ?><div class="empty-state"><i class="bi bi-check2-circle"></i><p>Nothing overdue. You're all caught up.</p></div><?php endif; foreach ($followUps as $lead): ?><a href="<?= e(url('leads/'.$lead['id'])) ?>"><span class="follow-icon"><i class="bi bi-calendar2-check"></i></span><div><strong><?= e($lead['name']) ?></strong><small><?= e($lead['company_name'] ?: 'Independent lead') ?></small></div><span class="follow-time <?= substr($lead['next_follow_up'],0,10) < date('Y-m-d') ? 'overdue' : '' ?>"><?= e(date('d M, g:i A', strtotime($lead['next_follow_up']))) ?></span><i class="bi bi-chevron-right"></i></a><?php endforeach; ?></div></section></div></div>
<?php if ($user['role'] === 'OWNER'): ?><section class="panel mt-3"><div class="panel-head"><div><span class="eyebrow">TEAM MOMENTUM</span><h2>Today's performance</h2></div><a href="<?= e(url('team')) ?>">Manage team <i class="bi bi-arrow-right"></i></a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>BDE</th><th>Active leads</th><th>Calls</th><th>Meetings</th><th>Follow-ups</th><th>Won</th></tr></thead><tbody><?php foreach ($team as $member): ?><tr><td><strong><?= e($member['name']) ?></strong><small class="d-block text-secondary"><?= e($member['email']) ?></small></td><td><?= (int)$member['active_leads'] ?></td><td><?= (int)$member['calls_today'] ?></td><td><?= (int)$member['meetings_today'] ?></td><td><?= (int)$member['follow_ups'] ?></td><td><span class="badge text-bg-success-subtle text-success-emphasis"><?= (int)$member['won_leads'] ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
